function evidence = f90_xrobo08_extract_reference_evidence(modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XROBO08_EXTRACT_REFERENCE_EVIDENCE One-session seven-scenario replay.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end
assert(isfile(officialScenarios), "SimuVerity:F90:XROBO08:OfficialScenarios", ...
    "Official scenarios are missing.");
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XROBO08:ReferenceAssetRoot", ...
    "Evaluator asset root is missing.");
referenceRoot = string(fileparts(modelPath));
mainRoot = fullfile(referenceRoot, "main");
dataRoot = fullfile(referenceRoot, "data");
official = jsondecode(fileread(officialScenarios));
modelFile = modelPath;
agentFile = fullfile(dataRoot, "kinovaBallBalanceAgent.mat");
parameterFile = fullfile(mainRoot, "kinova_params.m");
calcFile = fullfile(mainRoot, "calcMOI.m");
contactFile = fullfile(mainRoot, "cor2SpringDamperParams.m");
assert(strcmpi(localFilePresence(modelFile), string("present")), ...
    "SimuVerity:F90:XROBO08:ModelBinding", "Pinned root-model binding mismatch.");
assert(strcmpi(localFilePresence(agentFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO08:PolicyBinding", "Pinned policy binding mismatch.");
assert(strcmpi(localFilePresence(parameterFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO08:ParameterBinding", "Pinned parameter-script binding mismatch.");
assert(strcmpi(localFilePresence(calcFile), ...
    "present") && ...
    strcmpi(localFilePresence(contactFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO08:HelperBinding", "Pinned parameter helper binding mismatch.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XROBO08:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
outDir = outputDir;
assert(~isfolder(outDir), "SimuVerity:F90:XROBO08:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XROBO08:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(mainRoot, "-begin");
addpath(dataRoot, "-begin");
originalDirectory = pwd;
directoryCleanup = onCleanup(@() cd(originalDirectory)); %#ok<NASGU>
cd(mainRoot);

evidence = struct( ...
    "schema", "simuverity.f90-xrobo08-evidence.v1", ...
    "task_id", "F90-XROBO-08", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "";
try
    modelHandle = load_system(modelFile);
    model = string(get_param(modelHandle, "Name"));
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;

    localRunPinnedParameters(parameterFile, model);
    baseline = localBaselineFromBase;
    loadedPolicy = load(agentFile);
    policyName = localPolicyField(loadedPolicy);
    assignin("base", "f90_reference_agent", loadedPolicy.(policyName));
    set_param(model + "/RL Agent", "Agent", "f90_reference_agent");
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout", ...
        "FastRestart", "off");

    localExposeSupportedInitialVelocity(model);
    localInstallMeasurementTaps(model);
    localApplyScenario(baseline, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model);

    localApplyScenario(baseline, official.scenarios(1));
    set_param(model, "StopTime", "0.25");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            applied = localApplyScenario(baseline, scenario);
            rows(k).applied_parameters = applied;
            set_param(model, "StopTime", ...
                sprintf("%.17g", double(scenario.stop_time_s)));
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, ...
                double(scenario.stop_time_s));
            rows(k) = localFinalizeScenario(rows(k), outputs, ...
                scenario);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.root_model_file_presence_after = localFilePresence(modelFile);
evidence.policy_file_presence_after = localFilePresence(agentFile);
evidence.parameter_script_file_presence_after = localFilePresence(parameterFile);
evidence.binding_preserved = ...
    strcmpi(evidence.root_model_file_presence_after, ...
        string("present")) && ...
    strcmpi(evidence.policy_file_presence_after, ...
        "present") && ...
    strcmpi(evidence.parameter_script_file_presence_after, ...
        "present");
evidence.finished_at = localNow;
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
evidence.EVIDENCE_COMPLETE = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.nominal_smoke_pass && ...
    evidence.binding_preserved && numel(evidence.scenarios) == numel(official.scenarios) && ...
    validCount == numel(official.scenarios);
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
fprintf("F90_XROBO08_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d binding=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidence.binding_preserved, evidencePath);
end

function localRunPinnedParameters(parameterFile, model)
originalBlock = "rlKinovaBallBalance/Kinova Ball Balance/7 DOF Manipulator";
runtimeBlock = model + "/Kinova Ball Balance/7 DOF Manipulator";
assert(getSimulinkBlockHandle(runtimeBlock) > 0, ...
    "SimuVerity:ReferenceSetup:ManipulatorBlockMissing", ...
    "The loaded reference alias has no exact 7 DOF Manipulator block.");
parameterSource = string(fileread(parameterFile));
assert(count(parameterSource, originalBlock) == 2, ...
    "SimuVerity:ReferenceSetup:ParameterScriptContract", ...
    "The pinned parameter script no longer has its exact two model-bound calls.");
if runtimeBlock ~= originalBlock
    parameterSource = replace(parameterSource, originalBlock, runtimeBlock);
    assert(~contains(parameterSource, originalBlock), ...
        "SimuVerity:ReferenceSetup:ParameterScriptRewrite", ...
        "The pinned parameter script still targets the unloaded source model.");
end
evalin("base", parameterSource);
end

function localExposeSupportedInitialVelocity(model)
% The source 6-DOF joint already owns the ball translational initial
% conditions. Expose its dormant x/y velocity targets in memory only; zero
% remains identical to the pinned source and the SLX is never saved.
joint = string(model) + "/Kinova Ball Balance/6-DOF Joint";
set_param(joint, ...
    "PxVelocityTargetSpecify", "on", ...
    "PxVelocityTargetValue", "ball.dx0", ...
    "PyVelocityTargetSpecify", "on", ...
    "PyVelocityTargetValue", "ball.dy0");
end

function baseline = localBaselineFromBase
names = ["ball", "plate", "max_torque", "U0", "g", ...
    "R6_q0", "R7_q0", "coeff_restitution"];
baseline = struct;
for k = 1:numel(names)
    assert(evalin("base", "exist('" + names(k) + "','var')") == 1, ...
        "SimuVerity:F90:XROBO08:Baseline", ...
        "Parameter script did not create %s.", names(k));
    baseline.(names(k)) = evalin("base", names(k));
end
end

function name = localPolicyField(loaded)
names = string(fieldnames(loaded));
assert(~isempty(names), "SimuVerity:F90:XROBO08:SavedPolicy", ...
    "Pinned policy MAT file has no variables.");
preferred = ["agent", "saved_agent", "trainedAgent"];
name = "";
for k = 1:numel(preferred)
    if any(names == preferred(k))
        name = preferred(k);
        break
    end
end
if strlength(name) == 0 && numel(names) == 1
    name = names(1);
end
assert(strlength(name) > 0, "SimuVerity:F90:XROBO08:SavedPolicy", ...
    "Pinned policy variable could not be selected unambiguously.");
name = char(name);
end

function localInstallMeasurementTaps(model)
root = string(model);
plant = root + "/Kinova Ball Balance";
localDirectTap(root, root + "/RL Agent", 1, "f90_policy_action");
localDirectTap(root, plant, 1, "f90_observation");
localDirectTap(root, plant, 2, "f90_reward");
localDirectTap(root, plant, 3, "f90_done");
localDirectTap(plant, plant + "/Add", 1, "f90_applied_torque");
localDirectTap(plant, plant + "/Ball Sensing", 1, "f90_ball_state");
localDirectTap(plant, plant + "/Plate Sensing", 1, "f90_plate_q");
localDirectTap(plant, plant + "/Plate Sensing", 2, "f90_plate_qd");
localDirectTap(plant, plant + "/7 DOF Manipulator", 1, ...
    "f90_joint_state");
end

function localDirectTap(parent, source, port, variable)
sink = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(sink) < 0, ...
    "SimuVerity:F90:XROBO08:TapCollision", ...
    "Temporary measurement tap already exists: %s", sink);
add_block("simulink/Sinks/To Workspace", sink, ...
    "VariableName", variable, ...
    "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
sinkPorts = get_param(sink, "PortHandles");
assert(numel(sourcePorts.Outport) >= port && ...
    sourcePorts.Outport(port) > 0 && sinkPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO08:TapPort", ...
    "A required measurement source port is missing: %s#%d", ...
    source, port);
add_line(parent, sourcePorts.Outport(port), sinkPorts.Inport(1), ...
    "autorouting", "on");
end

function applied = localApplyScenario(baseline, scenario)
ball = baseline.ball;
ball.x0 = double(scenario.BallInitialX_m);
ball.y0 = double(scenario.BallInitialY_m);
ball.dx0 = double(scenario.BallInitialVX_mps);
ball.dy0 = double(scenario.BallInitialVY_mps);
ball.mass = baseline.ball.mass * double(scenario.BallMassScale);
ball.moi = calcMOI(ball.radius, ball.shell, ball.mass);
frictionScale = double(scenario.ContactFrictionScale);
ball.staticfriction = baseline.ball.staticfriction * frictionScale;
ball.dynamicfriction = baseline.ball.dynamicfriction * frictionScale;
[ball.stiffness, ball.damping, ball.transitionwidth] = ...
    cor2SpringDamperParams(baseline.coeff_restitution, ball.mass);
maxTorque = baseline.max_torque * ...
    double(scenario.TorqueAuthorityScale);
wristTorque = (-1.882 + ball.x0 * ball.mass * baseline.g) * ...
    cos(deg2rad(-65) - baseline.R6_q0);
handTorque = (0.0002349 - ball.y0 * ball.mass * baseline.g) * ...
    cos(deg2rad(-90) - baseline.R7_q0);
initialTorque = [wristTorque handTorque];

assignin("base", "ball", ball);
assignin("base", "max_torque", maxTorque);
assignin("base", "U0", initialTorque);
assignin("base", "BallInitialX_m", ball.x0);
assignin("base", "BallInitialY_m", ball.y0);
assignin("base", "BallInitialVX_mps", ball.dx0);
assignin("base", "BallInitialVY_mps", ball.dy0);
assignin("base", "BallMassScale", double(scenario.BallMassScale));
assignin("base", "ContactFrictionScale", frictionScale);
assignin("base", "TorqueAuthorityScale", ...
    double(scenario.TorqueAuthorityScale));
applied = struct( ...
    "ball_mass_kg", ball.mass, ...
    "static_friction", ball.staticfriction, ...
    "dynamic_friction", ball.dynamicfriction, ...
    "corrective_torque_range_Nm", maxTorque, ...
    "initial_torque_bias_Nm", initialTorque);
end

function localValidateSmoke(simOut)
required = { ...
    "f90_ball_state", 4; ...
    "f90_plate_q", 4; ...
    "f90_plate_qd", 4; ...
    "f90_joint_state", 4; ...
    "f90_policy_action", 2; ...
    "f90_applied_torque", 2; ...
    "f90_observation", 22; ...
    "f90_reward", 1; ...
    "f90_done", 1};
for k = 1:size(required, 1)
    localWorkspaceTimeseries(simOut, required{k, 1}, required{k, 2});
end
end

function outputs = localExtractOutputs(simOut, stopTime)
ball = localWorkspaceTimeseries(simOut, "f90_ball_state", 4);
plateQ = localWorkspaceTimeseries(simOut, "f90_plate_q", 4);
plateQd = localWorkspaceTimeseries(simOut, "f90_plate_qd", 4);
joint = localWorkspaceTimeseries(simOut, "f90_joint_state", 4);
action = localWorkspaceTimeseries(simOut, "f90_policy_action", 2);
torque = localWorkspaceTimeseries(simOut, "f90_applied_torque", 2);
observation = localWorkspaceTimeseries(simOut, "f90_observation", 22);
reward = localWorkspaceTimeseries(simOut, "f90_reward", 1);
done = localWorkspaceTimeseries(simOut, "f90_done", 1);
sampleTime = 0.02;
time = (0:sampleTime:stopTime)';
if time(end) < stopTime - sampleTime / 100
    time(end + 1, 1) = stopTime; %#ok<AGROW>
end
outputs = struct( ...
    "time_s", time, ...
    "ball_state", localInterp(ball, time, "linear"), ...
    "plate_state", [localInterp(plateQ, time, "linear"), ...
        localInterp(plateQd, time, "linear")], ...
    "actuated_joint_state", localInterp(joint, time, "linear"), ...
    "control_state", [localInterp(action, time, "previous"), ...
        localInterp(torque, time, "previous")], ...
    "task_state", [localInterp(reward, time, "previous"), ...
        localInterp(done, time, "previous")], ...
    "observation_state", ...
        localInterp(observation, time, "previous"));
end

function row = localFinalizeScenario(row, outputs, scenario)
allValues = [outputs.time_s; outputs.ball_state(:); ...
    outputs.plate_state(:); outputs.actuated_joint_state(:); ...
    outputs.control_state(:); outputs.task_state(:); ...
    outputs.observation_state(:)];
initialError = max(abs(outputs.ball_state(1, 1:4) - [ ...
    double(scenario.BallInitialX_m), ...
    double(scenario.BallInitialY_m), ...
    double(scenario.BallInitialVX_mps), ...
    double(scenario.BallInitialVY_mps)]));
row.simulation_pass = true;
row.scenario_application_pass = initialError <= 0.01;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) >= 2 && outputs.time_s(1) == 0 && ...
    outputs.time_s(end) >= double(scenario.stop_time_s) - 1e-6;
row.valid = row.required_evidence_pass && ...
    row.scenario_application_pass;
row.initial_state_max_error = initialError;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model)
root = string(model);
plant = root + "/Kinova Ball Balance";
contact = plant + "/Spatial" + newline + "Contact Force";
ball = plant + "/Ball";
plate = plant + "/Plate";
manipulator = plant + "/7 DOF Manipulator";
agent = root + "/RL Agent";
audit = struct( ...
    "pinned_feedback_controller_present", ...
        getSimulinkBlockHandle(agent) > 0, ...
    "physical_ball_present", getSimulinkBlockHandle(ball) > 0, ...
    "physical_plate_present", getSimulinkBlockHandle(plate) > 0, ...
    "spatial_contact_present", ...
        getSimulinkBlockHandle(contact) > 0, ...
    "articulated_manipulator_present", ...
        getSimulinkBlockHandle(manipulator) > 0, ...
    "controller_action_to_plant", ...
        localPortConnects(agent, 1, plant, 1), ...
    "observation_to_controller", ...
        localPortConnects(plant, 1, agent, 1), ...
    "reward_to_controller", ...
        localPortConnects(plant, 2, agent, 2), ...
    "termination_to_controller", ...
        localPortConnects(plant, 3, agent, 3), ...
    "action_scaled_before_torque", ...
        localPortConnects(plant + "/Gain", 1, ...
            plant + "/Reshape", 1) && ...
        localPortConnects(plant + "/Reshape", 1, ...
            plant + "/Add", 1), ...
    "applied_torque_to_manipulator", ...
        localPortConnects(plant + "/Add", 1, manipulator, 1), ...
    "ball_state_to_observation", ...
        localPortConnects(plant + "/Ball Sensing", 1, ...
            plant + "/Observation", 5), ...
    "plate_state_to_observation", ...
        localPortConnects(plant + "/Plate Sensing", 2, ...
            plant + "/Observation", 3), ...
    "joint_state_to_observation", ...
        localPortConnects(manipulator, 1, ...
            plant + "/Observation", 4), ...
    "contact_has_physical_connections", ...
        localPhysicalConnectionCount(contact) >= 2);
values = struct2cell(audit);
audit.core_path_qualified = all(cellfun(@(value) logical(value), values));
end

function pass = localPortConnects(source, outIndex, destination, inIndex)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(outIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function count = localPhysicalConnectionCount(block)
count = 0;
try
    handles = get_param(block, "LineHandles");
    if isfield(handles, "LConn")
        count = count + sum(handles.LConn > 0);
    end
    if isfield(handles, "RConn")
        count = count + sum(handles.RConn > 0);
    end
catch
end
end

function series = localWorkspaceTimeseries(simOut, name, columns)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XROBO08:WorkspaceTap", ...
    "Required measurement tap %s is missing or not Timeseries.", name);
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(value.Time) && ...
        size(data, 2) == numel(value.Time)
    data = data.';
end
assert(size(data, 1) == numel(value.Time) && ...
    size(data, 2) == columns, "SimuVerity:F90:XROBO08:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.", name);
series = struct("time", double(value.Time(:)), "values", data);
end

function values = localInterp(series, time, method)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XROBO08:EmptySeries", "Required series is empty.");
if numel(series.time) == 1
    values = repmat(series.values(1, :), numel(time), 1);
    return
end
[uniqueTime, uniqueIndices] = unique(series.time, "stable");
uniqueValues = series.values(uniqueIndices, :);
values = interp1(uniqueTime, uniqueValues, time, method, "extrap");
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "applied_parameters", struct, ...
    "simulation_pass", false, ...
    "scenario_application_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "initial_state_max_error", Inf, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", regexprep(string(ME.message), "[^\x20-\x7E]", "?"));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
try
    evalin("base", "clear f90_reference_agent");
catch
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XROBO08:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value, PrettyPrint=true), "UTF-8");
fwrite(fid, bytes, "uint8");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
